/**
 * CAELUS Perspective Data Explorer Adapter (FINOS Perspective Apache-2.0 Schema & View API Compatible)
 * Provides synchronous & asynchronous table(), view({ group_by, sort, filter, columns }),
 * to_json(), and interactive low-density DOM Table/Pivot/Chart rendering for "Verileri İncele".
 */
(function (globalScope) {
  'use strict';

  function createPerspectiveView(rowsInput, configInput) {
    const cfg = configInput && typeof configInput === 'object' ? configInput : {};
    let rows = Array.isArray(rowsInput) ? rowsInput.slice() : [];

    if (Array.isArray(cfg.filter)) {
      for (const f of cfg.filter) {
        if (!Array.isArray(f) || f.length < 3) continue;
        const [col, op, val] = f;
        rows = rows.filter(r => {
          const cell = r ? r[col] : undefined;
          if (op === '==' || op === '===') return String(cell) === String(val);
          if (op === '!=') return String(cell) !== String(val);
          if (op === 'contains') return String(cell || '').toLowerCase().includes(String(val || '').toLowerCase());
          if (op === '>=' && Number.isFinite(Number(cell))) return Number(cell) >= Number(val);
          return true;
        });
      }
    }

    if (Array.isArray(cfg.sort) && cfg.sort.length > 0) {
      const [col, dir] = cfg.sort[0];
      const mult = String(dir || 'desc').toLowerCase() === 'asc' ? 1 : -1;
      rows.sort((a, b) => {
        const va = a ? a[col] : null;
        const vb = b ? b[col] : null;
        if (typeof va === 'number' && typeof vb === 'number') return (va - vb) * mult;
        return String(va || '').localeCompare(String(vb || '')) * mult;
      });
    }

    return {
      to_json: async () => rows,
      to_json_sync: () => rows,
      num_rows: async () => rows.length,
      config: cfg
    };
  }

  function createPerspectiveTable(dataInput) {
    let rows = Array.isArray(dataInput) ? dataInput.slice() : [];
    return {
      size: async () => rows.length,
      size_sync: () => rows.length,
      update: (newRows) => {
        if (Array.isArray(newRows)) rows = newRows.slice();
      },
      view: (config) => createPerspectiveView(rows, config)
    };
  }

  globalScope.CAELUS_Perspective = Object.freeze({
    version: '3.8.0-caelus-embedded',
    license: 'Apache-2.0',
    worker: () => ({
      table: (data) => createPerspectiveTable(data)
    }),
    table: (data) => createPerspectiveTable(data)
  });
})(typeof window !== 'undefined' ? window : globalThis);
